create or replace function public.track_guest_request(request_reference text,tracking_token text) returns jsonb language plpgsql security definer set search_path='' as $fn$
declare result jsonb;
begin
select jsonb_build_object('reference',r.reference,'status',r.status,'container_size',r.container_size,'quantity',r.quantity,'pickup',r.pickup_location,'destination',r.destination_location,'required_at',r.required_at,'estimated_price',r.estimated_price,'price_status',r.price_status,'provider',o.name,'trip_reference',t.reference,'trip_status',t.status,'scheduled_start',t.scheduled_start,'scheduled_end',t.scheduled_end,'delivered_at',t.delivered_at,'delivery_recipient',d.recipient_name,'open_exception',ex.exception_type,'trip_events',coalesce((select jsonb_agg(jsonb_build_object('status',e.to_status,'notes',e.notes,'occurred_at',e.occurred_at) order by e.occurred_at) from public.trip_status_events e where e.trip_id=t.id),'[]'::jsonb)) into result from public.transport_requests r left join public.company_assignments a on a.request_id=r.id left join public.organizations o on o.id=a.provider_id left join public.allocations al on al.request_id=r.id left join public.trips t on t.allocation_id=al.id left join public.deliveries d on d.trip_id=t.id left join lateral(select exception_type from public.exceptions where trip_id=t.id and status='open' order by reported_at desc limit 1) ex on true where upper(r.reference)=upper(trim(request_reference)) and r.tracking_token_hash=encode(extensions.digest(tracking_token,'sha256'),'hex') limit 1;
return result;
end;$fn$;
grant execute on function public.track_guest_request(text,text) to anon,authenticated;
